// Package server implements the kvhttp HTTP API on top of a store.Store.
package server

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strconv"
	"strings"

	"kvhttp/internal/store"
)

const (
	// MaxKeyLen is the maximum key length in bytes.
	MaxKeyLen = 64
	// MaxValueBytes is the maximum size of a stored value.
	MaxValueBytes = 1 << 20
)

// Handler serves the kvhttp routes.
type Handler struct {
	store *store.Store
}

// New returns a Handler backed by s.
func New(s *store.Store) *Handler {
	return &Handler{store: s}
}

func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	// Route on the raw request target so percent-escapes are not decoded
	// into otherwise valid keys.
	path := r.RequestURI
	switch {
	case path == "/health":
		if r.Method != http.MethodGet {
			notAllowed(w, "GET")
			return
		}
		w.Header().Set("Content-Type", "text/plain; charset=utf-8")
		writeBody(w, http.StatusOK, []byte("ok"))
	case path == "/kv":
		if r.Method != http.MethodGet {
			notAllowed(w, "GET")
			return
		}
		h.list(w)
	case strings.HasPrefix(path, "/kv/"):
		key := path[len("/kv/"):]
		if !ValidKey(key) {
			status(w, http.StatusBadRequest)
			return
		}
		switch r.Method {
		case http.MethodGet:
			h.get(w, key)
		case http.MethodPut:
			h.put(w, r, key)
		case http.MethodDelete:
			if h.store.Delete(key) {
				status(w, http.StatusNoContent)
			} else {
				status(w, http.StatusNotFound)
			}
		default:
			notAllowed(w, "GET, PUT, DELETE")
		}
	default:
		status(w, http.StatusNotFound)
	}
}

func (h *Handler) list(w http.ResponseWriter) {
	body, err := json.Marshal(h.store.Keys())
	if err != nil {
		status(w, http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	writeBody(w, http.StatusOK, body)
}

func (h *Handler) get(w http.ResponseWriter, key string) {
	v, ok := h.store.Get(key)
	if !ok {
		status(w, http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/octet-stream")
	writeBody(w, http.StatusOK, v)
}

func (h *Handler) put(w http.ResponseWriter, r *http.Request, key string) {
	if r.ContentLength > MaxValueBytes {
		status(w, http.StatusRequestEntityTooLarge)
		return
	}
	value, err := io.ReadAll(http.MaxBytesReader(w, r.Body, MaxValueBytes))
	if err != nil {
		if _, tooLarge := errors.AsType[*http.MaxBytesError](err); tooLarge {
			status(w, http.StatusRequestEntityTooLarge)
		}
		// Otherwise the client went away or timed out; nothing to reply to.
		return
	}
	if h.store.Put(key, value) {
		status(w, http.StatusCreated)
	} else {
		status(w, http.StatusOK)
	}
}

// ValidKey reports whether k matches [A-Za-z0-9_-]{1,64}.
func ValidKey(k string) bool {
	if len(k) == 0 || len(k) > MaxKeyLen {
		return false
	}
	for i := 0; i < len(k); i++ {
		c := k[i]
		switch {
		case c >= 'A' && c <= 'Z', c >= 'a' && c <= 'z', c >= '0' && c <= '9', c == '_', c == '-':
		default:
			return false
		}
	}
	return true
}

func writeBody(w http.ResponseWriter, code int, body []byte) {
	w.Header().Set("Content-Length", strconv.Itoa(len(body)))
	w.WriteHeader(code)
	_, _ = w.Write(body)
}

func status(w http.ResponseWriter, code int) {
	if code != http.StatusNoContent {
		w.Header().Set("Content-Length", "0")
	}
	w.WriteHeader(code)
}

func notAllowed(w http.ResponseWriter, allow string) {
	w.Header().Set("Allow", allow)
	status(w, http.StatusMethodNotAllowed)
}

package server

import (
	"bytes"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"kvhttp/internal/store"
)

func do(t *testing.T, h http.Handler, method, target, body string) *http.Response {
	t.Helper()
	var r io.Reader
	if body != "" {
		r = strings.NewReader(body)
	}
	req := httptest.NewRequest(method, target, r)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec.Result()
}

func TestRoutes(t *testing.T) {
	h := New(store.New())
	tests := []struct {
		method, target, body string
		wantStatus           int
		wantBody             string
	}{
		{"GET", "/health", "", 200, "ok"},
		{"POST", "/health", "", 405, ""},
		{"GET", "/kv", "", 200, "[]"},
		{"PUT", "/kv/b", "hello", 201, ""},
		{"PUT", "/kv/b", "world", 200, ""},
		{"PUT", "/kv/a", "", 201, ""},
		{"GET", "/kv/b", "", 200, "world"},
		{"GET", "/kv/a", "", 200, ""},
		{"GET", "/kv", "", 200, `["a","b"]`},
		{"PATCH", "/kv/a", "", 405, ""},
		{"POST", "/kv", "", 405, ""},
		{"DELETE", "/kv/a", "", 204, ""},
		{"DELETE", "/kv/a", "", 404, ""},
		{"GET", "/kv/a", "", 404, ""},
		{"GET", "/kv/", "", 400, ""},
		{"GET", "/kv/bad.key", "", 400, ""},
		{"GET", "/kv/a/b", "", 400, ""},
		{"GET", "/kv/%41", "", 400, ""},
		{"GET", "/kv/" + strings.Repeat("k", 65), "", 400, ""},
		{"GET", "/kv/" + strings.Repeat("k", 64), "", 404, ""},
		{"GET", "/nope", "", 404, ""},
		{"GET", "/", "", 404, ""},
	}
	for _, tc := range tests {
		res := do(t, h, tc.method, tc.target, tc.body)
		got, _ := io.ReadAll(res.Body)
		if res.StatusCode != tc.wantStatus || string(got) != tc.wantBody {
			t.Errorf("%s %s: got %d %q, want %d %q", tc.method, tc.target, res.StatusCode, got, tc.wantStatus, tc.wantBody)
		}
	}
}

func TestValueLimit(t *testing.T) {
	h := New(store.New())
	max := string(bytes.Repeat([]byte{0xff}, MaxValueBytes))
	if res := do(t, h, "PUT", "/kv/big", max); res.StatusCode != 201 {
		t.Fatalf("1 MiB value: status %d", res.StatusCode)
	}
	if res := do(t, h, "PUT", "/kv/big", max+"x"); res.StatusCode != 413 {
		t.Fatalf("oversized value: status %d", res.StatusCode)
	}
}

// Package store provides a thread-safe in-memory key-value store.
package store

import (
	"maps"
	"slices"
	"sync"
)

// Store maps string keys to byte values. The zero value is not usable; call New.
type Store struct {
	mu   sync.RWMutex
	data map[string][]byte
}

// New returns an empty store.
func New() *Store {
	return &Store{data: make(map[string][]byte)}
}

// Put stores value under key, taking ownership of the slice.
// It reports whether the key was newly created.
func (s *Store) Put(key string, value []byte) (created bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, exists := s.data[key]
	s.data[key] = value
	return !exists
}

// Get returns the value stored under key. The returned slice must not be modified.
func (s *Store) Get(key string) ([]byte, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.data[key]
	return v, ok
}

// Delete removes key and reports whether it was present.
func (s *Store) Delete(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.data[key]; !ok {
		return false
	}
	delete(s.data, key)
	return true
}

// Keys returns all keys sorted ascending. The result is never nil.
func (s *Store) Keys() []string {
	s.mu.RLock()
	keys := make([]string, 0, len(s.data))
	keys = slices.AppendSeq(keys, maps.Keys(s.data))
	s.mu.RUnlock()
	slices.Sort(keys)
	return keys
}

package store

import (
	"slices"
	"testing"
)

func TestStore(t *testing.T) {
	s := New()
	if got := s.Keys(); got == nil || len(got) != 0 {
		t.Fatalf("Keys on empty store = %#v, want empty non-nil", got)
	}
	if !s.Put("b", []byte("1")) {
		t.Fatal("first Put should create")
	}
	if s.Put("b", []byte("2")) {
		t.Fatal("second Put should replace")
	}
	s.Put("a", nil)
	if v, ok := s.Get("b"); !ok || string(v) != "2" {
		t.Fatalf("Get(b) = %q, %v", v, ok)
	}
	if got := s.Keys(); !slices.Equal(got, []string{"a", "b"}) {
		t.Fatalf("Keys = %v", got)
	}
	if !s.Delete("a") || s.Delete("a") {
		t.Fatal("Delete should succeed once")
	}
	if _, ok := s.Get("a"); ok {
		t.Fatal("deleted key still present")
	}
}

// Command kvhttp is an HTTP/1.1 in-memory key-value server.
//
// Usage: app <port>
package main

import (
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"strconv"
	"time"

	"kvhttp/internal/server"
	"kvhttp/internal/store"
)

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintf(os.Stderr, "usage: %s <port>\n", os.Args[0])
		os.Exit(2)
	}
	port, err := strconv.Atoi(os.Args[1])
	if err != nil || port < 1 || port > 65535 {
		fmt.Fprintf(os.Stderr, "invalid port: %s\n", os.Args[1])
		os.Exit(2)
	}

	ln, err := net.Listen("tcp", net.JoinHostPort("127.0.0.1", strconv.Itoa(port)))
	if err != nil {
		log.Fatal(err)
	}

	srv := &http.Server{
		Handler:           server.New(store.New()),
		ReadHeaderTimeout: 10 * time.Second,
		ReadTimeout:       30 * time.Second,
		WriteTimeout:      30 * time.Second,
		IdleTimeout:       30 * time.Second,
		MaxHeaderBytes:    16 << 10,
	}
	log.Fatal(srv.Serve(ln))
}
